let LANG = (() => { try { return localStorage.getItem("lang") || "en"; } catch { return "en"; } })();
if (!I18N[LANG]) LANG = "en";
function t(key, vars) {
  let s = I18N[LANG][key] ?? I18N.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split("{" + k + "}").join(v ?? "?");
  return s;
}
const L = (obj) => (obj && (obj[LANG] ?? obj.en)) ?? "";
function applyI18n(root = document) {
  root.querySelectorAll("[data-i]").forEach((el) => { el.textContent = t(el.dataset.i); });
  root.querySelectorAll("[data-iph]").forEach((el) => { el.placeholder = t(el.dataset.iph); });
  root.querySelectorAll("[data-ititle]").forEach((el) => { el.title = t(el.dataset.ititle); });
  document.documentElement.lang = LANG;
}
function setLang(l) { LANG = I18N[l] ? l : "en"; try { localStorage.setItem("lang", LANG); } catch { /* private mode */ } }
